export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  sourcePath: string;
  slug: string;
  title: string;
  date: string;
  tags: string[];
  content: string;
  html: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Frontmatter, Page } from './types';

function normalizeTag(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((tag) => String(tag).trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
  }
  return [];
}

function normalizeTitle(fm: Frontmatter, filePath: string): string {
  if (typeof fm.title === 'string' && fm.title.trim()) {
    return fm.title.trim();
  }
  return path.basename(filePath, path.extname(filePath));
}

function normalizeDate(fm: Frontmatter): string {
  if (typeof fm.date === 'string' && fm.date.trim()) {
    return fm.date.trim();
  }
  return '';
}

function toSlug(sourcePath: string): string {
  const relative = sourcePath.replace(/\\/g, '/');
  const parsed = path.parse(relative);
  const base = parsed.name === 'index' ? '' : parsed.name;
  const dir = parsed.dir ? `${parsed.dir}/` : '';
  return `${dir}${base}`.replace(/\/+$/, '') || 'index';
}

export function parseMarkdownFile(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf8');
  const { data, content } = matter(raw);
  const fm = (data || {}) as Frontmatter;

  const html = marked.parse(content) as string;

  return {
    sourcePath: filePath,
    slug: toSlug(filePath),
    title: normalizeTitle(fm, filePath),
    date: normalizeDate(fm),
    tags: normalizeTag(fm.tags),
    content,
    html,
  };
}

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

import { Page } from './types';
import { escapeHtml } from './parser';

function tagsHtml(tags: string[]): string {
  if (tags.length === 0) return '';
  const chips = tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join('');
  return `<div class="tags">${chips}</div>`;
}

export function renderPage(page: Page): string {
  const title = escapeHtml(page.title);
  const date = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
  </header>
  <main>
    <article>
      <h1>${title}</h1>
      ${date ? `<p class="date">${date}</p>` : ''}
      ${tagsHtml(page.tags)}
      <div class="content">
${page.html}
      </div>
    </article>
  </main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => {
    if (a.date && b.date) {
      return a.date < b.date ? 1 : a.date > b.date ? -1 : 0;
    }
    return a.title.localeCompare(b.title);
  });

  const items = sorted
    .map((page) => {
      const date = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time> ` : '';
      return `    <li>
      <a href="${escapeHtml(page.slug)}.html"><h2>${escapeHtml(page.title)}</h2></a>
      ${date ? `<span class="date">${date}</span>` : ''}
      ${tagsHtml(page.tags)}
    </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Home</title>
</head>
<body>
  <header><h1>Site</h1></header>
  <main>
    <ul class="pages">
${items}
    </ul>
  </main>
</body>
</html>
`;
}

import fs from 'fs';
import path from 'path';
import { parseMarkdownFile } from './parser';
import { renderIndex, renderPage } from './template';
import { Page } from './types';

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';

export interface BuildOptions {
  contentDir?: string;
  outputDir?: string;
}

function collectMarkdownFiles(dir: string): string[] {
  const results: string[] = [];
  if (!fs.existsSync(dir)) {
    return results;
  }
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  entries.sort((a, b) => a.name.localeCompare(b.name));
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectMarkdownFiles(fullPath));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(fullPath);
    }
  }
  return results;
}

function ensureCleanDir(dir: string): void {
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
}

export function build(options: BuildOptions = {}): Page[] {
  const contentDir = path.resolve(options.contentDir ?? DEFAULT_CONTENT_DIR);
  const outputDir = path.resolve(options.outputDir ?? DEFAULT_OUTPUT_DIR);

  const files = collectMarkdownFiles(contentDir);
  const pages = files.map(parseMarkdownFile);

  ensureCleanDir(outputDir);

  for (const page of pages) {
    const fileName = `${page.slug}.html`;
    const filePath = path.join(outputDir, fileName);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, renderPage(page), 'utf8');
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf8');

  return pages;
}

#!/usr/bin/env node
import { build, BuildOptions } from './ssg';

const DEFAULT_COMMAND = 'build';

function printUsage(): void {
  console.log(`Usage:
  ssg build [options]

Options:
  --content <dir>   Source directory for Markdown files (default: ./content)
  --output <dir>    Output directory for generated HTML (default: ./dist)
  --help            Show this help`);
}

function parseArgs(argv: string[]): { command: string; options: BuildOptions; help: boolean } {
  const options: BuildOptions = {};
  let help = false;
  let command = DEFAULT_COMMAND;

  let idx = 0;
  while (idx < argv.length) {
    const arg = argv[idx];
    switch (arg) {
      case '--help':
      case '-h':
        help = true;
        idx += 1;
        break;
      case '--content':
        options.contentDir = argv[idx + 1];
        idx += 2;
        break;
      case '--output':
        options.outputDir = argv[idx + 1];
        idx += 2;
        break;
      default:
        if (arg.startsWith('-')) {
          idx += 1;
        } else {
          command = arg;
          idx += 1;
        }
    }
  }

  return { command, options, help };
}

function main(): void {
  const { command, options, help } = parseArgs(process.argv.slice(2));

  if (help || command !== 'build') {
    printUsage();
    if (command !== 'build') {
      process.exitCode = 1;
    }
    return;
  }

  const pages = build(options);
  console.log(`Generated ${pages.length} page(s) into ${options.outputDir ?? './dist'}`);
}

if (require.main === module) {
  main();
}

export { parseArgs, main };

import fs from 'fs';
import os from 'os';
import path from 'path';
import { parseMarkdownFile } from '../src/parser';

function makeTempFile(content: string, name = 'page.md'): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
  const filePath = path.join(dir, name);
  fs.writeFileSync(filePath, content, 'utf8');
  return filePath;
}

describe('parseMarkdownFile', () => {
  it('parses frontmatter and renders markdown to HTML', () => {
    const file = makeTempFile(
      `---
title: My Page
date: 2024-03-01
tags: [a, b]
---

Hello **world**`
    );
    const page = parseMarkdownFile(file);

    expect(page.title).toBe('My Page');
    expect(page.date).toBe('2024-03-01');
    expect(page.tags).toEqual(['a', 'b']);
    expect(page.html).toContain('<strong>world</strong>');
    expect(page.html).toContain('Hello');
    expect(page.sourcePath).toBe(file);
  });

  it('falls back to filename for title when frontmatter is missing', () => {
    const file = makeTempFile('Just body text.', 'no-title.md');
    const page = parseMarkdownFile(file);

    expect(page.title).toBe('no-title');
    expect(page.date).toBe('');
    expect(page.tags).toEqual([]);
  });

  it('supports comma-separated tags', () => {
    const file = makeTempFile(
      `---
tags: alpha, beta
---
Body.`
    );
    const page = parseMarkdownFile(file);
    expect(page.tags).toEqual(['alpha', 'beta']);
  });

  it('computes a slug from the relative file path', () => {
    const file = makeTempFile('Body.', 'about.md');
    const page = parseMarkdownFile(file);
    expect(page.slug).toBe('about');
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { build } from '../src/ssg';

function makeTempContentDir(files: Record<string, string>): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-content-'));
  for (const [rel, content] of Object.entries(files)) {
    const filePath = path.join(dir, rel);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content, 'utf8');
  }
  return dir;
}

describe('build', () => {
  it('generates an HTML page per markdown file and an index', () => {
    const contentDir = makeTempContentDir({
      'about.md': `---
title: About
date: 2024-01-01
---
About me.`,
      'posts/hello.md': `---
title: Hello
date: 2024-06-01
tags: [demo]
---
Hi there.`,
    });
    const outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-out-'));

    const pages = build({ contentDir, outputDir });

    expect(pages).toHaveLength(2);
    expect(fs.existsSync(path.join(outputDir, 'about.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'posts/hello.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const about = fs.readFileSync(path.join(outputDir, 'about.html'), 'utf8');
    expect(about).toContain('<title>About</title>');
    expect(about).toContain('About me.');

    const index = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(index).toContain('about.html');
    expect(index).toContain('posts/hello.html');
    expect(index).toContain('<h2>Hello</h2>');
  });

  it('cleans the output directory before building', () => {
    const contentDir = makeTempContentDir({
      'one.md': '# One',
    });
    const outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-out-'));
    fs.writeFileSync(path.join(outputDir, 'stale.txt'), 'old', 'utf8');

    build({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'stale.txt'))).toBe(false);
    expect(fs.existsSync(path.join(outputDir, 'one.html'))).toBe(true);
  });

  it('uses default content and output directories', () => {
    const cwd = process.cwd();
    const sandbox = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-sandbox-'));
    fs.mkdirSync(path.join(sandbox, 'content'));
    fs.writeFileSync(path.join(sandbox, 'content', 'x.md'), '---\ntitle: X\n---\nBody.');

    try {
      process.chdir(sandbox);
      const pages = build();
      expect(pages).toHaveLength(1);
      expect(fs.existsSync(path.join(sandbox, 'dist', 'x.html'))).toBe(true);
      expect(fs.existsSync(path.join(sandbox, 'dist', 'index.html'))).toBe(true);
    } finally {
      process.chdir(cwd);
    }
  });

  it('handles an empty content directory gracefully', () => {
    const contentDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-empty-'));
    const outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-out-'));

    const pages = build({ contentDir, outputDir });

    expect(pages).toHaveLength(0);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });
});

import { parseArgs } from '../src/cli';

describe('parseArgs', () => {
  it('parses the build command with defaults', () => {
    const { command, options, help } = parseArgs(['build']);
    expect(command).toBe('build');
    expect(options.contentDir).toBeUndefined();
    expect(options.outputDir).toBeUndefined();
    expect(help).toBe(false);
  });

  it('parses --content and --output flags', () => {
    const { command, options } = parseArgs(['build', '--content', 'src/pages', '--output', 'public']);
    expect(command).toBe('build');
    expect(options.contentDir).toBe('src/pages');
    expect(options.outputDir).toBe('public');
  });

  it('defaults the command to build when omitted', () => {
    const { command } = parseArgs(['--content', 'pages']);
    expect(command).toBe('build');
  });

  it('flags help when --help is passed', () => {
    const { help } = parseArgs(['build', '--help']);
    expect(help).toBe(true);
  });
});

